public class Main {
    static void boost(int score) {
        score = score + 50;
        System.out.println("Inside: " + score);
    }
    public static void main(String[] args) {
        int score = 10;
        boost(score);
        System.out.println("Outside: " + score);
    }
}

public class Main {
    static void bump(int[] nums) {
        nums[0] = nums[0] + 100;
    }
    public static void main(String[] args) {
        int[] nums = {5, 6, 7};
        bump(nums);
        System.out.println(nums[0]);
    }
}

